                if (checked) {
                    g.setColor(Color.WHITE);
                    g.drawLine(x + 4, y + 8, x + 7, y + 11); g.drawLine(x + 7, y + 11, x + 12, y + 5);
                    g.drawLine(x + 4, y + 9, x + 7, y + 12); g.drawLine(x + 7, y + 12, x + 12, y + 6);
