    private JButton sizeResetButton(String text, boolean taken)
    {
        JButton reset = button(text);
        reset.setAlignmentX(LEFT_ALIGNMENT);
        reset.addActionListener(e -> {
            String name = taken ? "damage taken" : "damage dealt";
